    Assert.assertEquals(1, commands.get(hostId).size());
    CancelCommand cancelCommand = (CancelCommand) commands.get(hostId).get(0);
    Assert.assertEquals(cancelCommand.getTargetTaskId(), namenodeCmdTaskId);
