    // difference in hash only
    MetadataUpdateEvent event2 = new MetadataUpdateEvent(null, null, null, UpdateEventType.CREATE);
    event2.setHash("02");
    String eventHash2 = metadataHolder.getHash(event2);
    // the same hash, but the body was changed
    MetadataUpdateEvent event3 = new MetadataUpdateEvent(null, null, null, UpdateEventType.UPDATE);
    event3.setHash("01");
