    commandCount = 0;
    for (HostRoleCommand command : commands) {
        if (command.getRoleCommand() == RoleCommand.START) {
            Assert.assertTrue(command.getHostName().equals(host3));
            commandCount++;
        }
    }
    Assert.assertEquals("Expect only one task.", 1, commandCount);
