@Test
public void testJMXTemporal() {
    TreeSet<String> set = new TreeSet<>();
    for (Resource.Type type : Resource.Type.values()) {
        Map<String, Map<String, PropertyInfo>> jids = PropertyHelper.getJMXPropertyIds(type);
