@Test(timeout = 20000)
public void testDatabaseMetricSourcePublish() throws InterruptedException {
    Map<String, Long> metricsMap = new HashMap<>();
    // Should be accepted.
    metricsMap.put("Timer.UpdateObjectQuery.HostRoleCommandEntity", 10000l);
    // Should be accepted.
    metricsMap.put("Timer.UpdateObjectQuery.HostRoleCommandEntity.SqlPrepare", 5000l);
    // Should be accepted.
    metricsMap.put("Timer.DirectReadQuery", 6000l);
    //Should be discarded
    metricsMap.put("Timer.ReadAllQuery.StackEntity.StackEntity.findByNameAndVersion.SqlPrepare", 15000l);
    // Should be accepted & should add a computed metric.
    metricsMap.put("Counter.UpdateObjectQuery.HostRoleCommandEntity", 10l);
    //Should be discarded
    metricsMap.put("Counter.ReadObjectQuery.RequestEntity.request", 4330l);
    // Should be accepted.
    metricsMap.put("Counter.ReadObjectQuery.MetainfoEntity.readMetainfoEntity.CacheMisses", 15l);
    DatabaseMetricsSource source = new DatabaseMetricsSource();
    MetricsConfiguration configuration = MetricsConfiguration.getSubsetConfiguration(MetricsConfiguration.getMetricsConfiguration(), "source.database.");
    MetricsSink sink = EasyMock.createMock(AmbariMetricSinkImpl.class);
    Capture<List<SingleMetric>> metricsCapture = EasyMock.newCapture();
    sink.publish(capture(metricsCapture));
    expectLastCall().once();
    replay(sink);
    source.init(configuration, sink);
    source.start();
    source.publish(metricsMap);
    Thread.sleep(5000l);
    verify(sink);
    Assert.assertTrue(metricsCapture.getValue().size() == 6);
}

@Test
public void testDatabaseMetricsSourceAcceptMetric() {
    DatabaseMetricsSource source = new DatabaseMetricsSource();
    MetricsConfiguration configuration = MetricsConfiguration.getSubsetConfiguration(MetricsConfiguration.getMetricsConfiguration(), "source.database.");
    MetricsSink sink = new TestAmbariMetricsSinkImpl();
