public void testCRUD() {
    Map<String, SettingEntity> entities = new HashMap<>();
    //Create
    for (int i = 0; i < 3; i++) {
        SettingEntity entity = new SettingEntity();
        entity.setName("motd" + i);
        entity.setContent("test content" + i);
        entity.setUpdatedBy("ambari");
