        dbAccessor.insertRow(targetTableName, new String[] { "id", "col1", "col2", "col3" }, new String[] { i.toString(), String.format("'1,%s'", i), String.format("'2,%s'", i * 2), String.format("'3,%s'", i * 3) }, false);
