    Assert.assertEquals(3, dataMap.size());
    Assert.assertEquals("aaa", dataMap.get("key1"));
    Assert.assertEquals("bbb", dataMap.get("key2"));
    Assert.assertEquals("ccc", dataMap.get("key3"));
