        for (JobKey jobKey : scheduler.getJobKeys(GroupMatcher.jobGroupEquals(ExecutionJob.LINEAR_EXECUTION_JOB_GROUP))) {
            LOG.info("Found job identified by: " + jobKey);
            String jobName = jobKey.getName();
