@Test
public void testReplaceVariables() throws AmbariException {
    Map<String, Map<String, String>> configurations = new HashMap<String, Map<String, String>>() {

        {
            put("", new HashMap<String, String>() {

                {
                    put("global_variable", "Hello World");
                    put("variable-name", "dash");
                    put("variable_name", "underscore");
                    put("variable.name", "dot");
                }
            });
            put("config_type", new HashMap<String, String>() {

                {
                    put("variable-name", "config_type_dash");
                    put("variable_name", "config_type_underscore");
                    put("variable.name", "config_type_dot");
                }
            });
            put("config.type", new HashMap<String, String>() {

                {
                    put("variable-name", "config.type_dash");
                    put("variable_name", "config.type_underscore");
                    put("variable.name", "config.type_dot");
                }
            });
            put("config-type", new HashMap<String, String>() {

                {
                    put("variable.name", "Replacement1");
                    put("variable.name1", "${config-type2/variable.name}");
                    put("variable.name2", "");
                }
            });
            put("config-type2", new HashMap<String, String>() {

                {
                    put("variable.name", "Replacement2");
                    // This essentially references itself.
                    put("self_reference", "${config-type2/self_reference}");
                    put("${config-type/variable.name}_reference", "Replacement in the key");
                }
            });
        }
    };
    assertEquals("concrete", helper.replaceVariables("concrete", configurations));
    assertEquals("Hello World", helper.replaceVariables("${global_variable}", configurations));
    assertEquals("Replacement1", helper.replaceVariables("${config-type/variable.name}", configurations));
    assertEquals("Replacement1|Replacement2", helper.replaceVariables("${config-type/variable.name}|${config-type2/variable.name}", configurations));
    assertEquals("Replacement1|Replacement2|${config-type3/variable.name}", helper.replaceVariables("${config-type/variable.name}|${config-type2/variable.name}|${config-type3/variable.name}", configurations));
    assertEquals("Replacement2|Replacement2", helper.replaceVariables("${config-type/variable.name1}|${config-type2/variable.name}", configurations));
    assertEquals("Replacement1_reference", helper.replaceVariables("${config-type/variable.name}_reference", configurations));
    assertEquals("dash", helper.replaceVariables("${variable-name}", configurations));
    assertEquals("underscore", helper.replaceVariables("${variable_name}", configurations));
    assertEquals("config_type_dot", helper.replaceVariables("${config_type/variable.name}", configurations));
    assertEquals("config_type_dash", helper.replaceVariables("${config_type/variable-name}", configurations));
    assertEquals("config_type_underscore", helper.replaceVariables("${config_type/variable_name}", configurations));
    assertEquals("config.type_dot", helper.replaceVariables("${config.type/variable.name}", configurations));
    assertEquals("config.type_dash", helper.replaceVariables("${config.type/variable-name}", configurations));
    assertEquals("config.type_underscore", helper.replaceVariables("${config.type/variable_name}", configurations));
    assertEquals("dot", helper.replaceVariables("${variable.name}", configurations));
    // Replacement yields an empty string
    assertEquals("", helper.replaceVariables("${config-type/variable.name2}", configurations));
    // This might cause an infinite loop... we assume protection is in place...
    try {
        assertEquals("${config-type2/self_reference}", helper.replaceVariables("${config-type2/self_reference}", configurations));
        Assert.fail(String.format("%s expected to be thrown", AmbariRuntimeException.class.getName()));
    } catch (AmbariRuntimeException e) {
        // This is expected...
    }
}

@Test
public void testReplaceVariablesRecursive() throws AmbariException {
    Map<String, Map<String, String>> configurations = new HashMap<String, Map<String, String>>() {

        {
            put("", new HashMap<String, String>());
            put("data", new HashMap<String, String>() {

                {
                    put("data_host1.example.com", "host 1 data");
                    put("data_host2.example.com", "host 2 data");
                    put("data_host3.example.com", "host 3 data");
                }
            });
        }
    };
    configurations.get("").put("h", "host");
    // Shows ${h} was replaced
    assertEquals("${data/data_${host}}", helper.replaceVariables("${data/data_${${h}}}", configurations));
    // data_host.example.com does not exist in the data configuration
    configurations.get("").put("host", "host.example.com");
    // Shows ${host} was replaced
    assertEquals("${data/data_host.example.com}", helper.replaceVariables("${data/data_${${h}}}", configurations));
    for (int i = 1; i <= 3; i++) {
        configurations.get("").put("host", String.format("host%d.example.com", i));
        assertEquals(String.format("host %d data", i), helper.replaceVariables("${data/data_${${h}}}", configurations));
    }
}

