" + "    </service>
" + "  </services>
" + "</metainfo>
";
    serviceInfoMap = getServiceInfo(serviceInfoXml);
    service = serviceInfoMap.get("HBASE");
    assertTrue(service.isCredentialStoreSupported());
    assertFalse(service.isCredentialStoreEnabled());
}

