    expect(request.getComponents()).andReturn(ImmutableSet.of(Component.of("KAFKA_BROKER", ProvisionAction.INSTALL_AND_START, "c7401", "c7402", "c7403"), Component.of("KAFKA_BROKER", ProvisionAction.INSTALL_ONLY, "c7402", "c7403", "c7404")));
