Service.proxyuser.knox.hosts\": \"somevalue\"" + "              }" + "            }," + "            {" + "              \"falcon-runtime.properties\": {" + "                \"*.falcon.service.ProxyUserService.proxyuser.knox.groups\": \"somevalue\"," + "                \"*.falcon.service.ProxyUserService.proxyuser.knox.hosts\": \"somevalue\"" + "              }" + "            }," + "            {" + "              \"some-env\": {" + "                \"groups\": \"${hadoop-env/proxyuser_group}\"," + "                \"hosts\": \"${clusterHostInfo/existing_service_master_hosts}\"" + "              }" + "            }" + "          ]" + "        }" + "      ]" + "    }," + "    {" + "      \"name\": \"NOT_SPARK\"," + "      \"configurations\": [" + "        {" + "          \"not-livy-conf\": {" + "            \"property1\": \"true\"," + "            \"property2\": \"true\"," + "            \"livy.superusers\": \"somevalue\"" + "          }" + "        }," + "        {" + "          \"some2-env\": {" + "            \"groups\": \"${hadoop-env/proxyuser_group}\"," + "            \"hosts\": \"${clusterHostInfo/existing_service_master_hosts}\"" + "          }" + "        }" + "      ]" + "    }" + "  ]" + "}";
    Type type = new TypeToken<Map<String, Object>>() {
