@Test
public void retainsTasksUntilStarted() {
    final int taskCount = 60;
    final AtomicInteger counter = new AtomicInteger();
    ManagedThreadPoolExecutor executor = createExecutor(10);
    for (int i = 0; i < taskCount; ++i) {
